export function createProposalDraftFromRenewal(renewal: MarketingRenewal, previousProposal: MarketingProposal | undefined, usePreviousPackage: boolean, rateCards: MarketingRateCard[], now = new Date().toISOString()): { proposal?: MarketingProposal; error?: string } { const items = usePreviousPackage && previousProposal ? previousProposal.items.map((item) => ({ id: createId('item', now), product: item.product, productId: item.productId, placementId: item.placementId, productGroup: item.productGroup, description: item.description, quantity: item.quantity, listPrice: '', discount: '', finalPrice: '', notes: '' })) : []; return createProposal({ advertiserId: renewal.advertiserId, primaryContactId: undefined, title: 'Renewal Proposal', campaignObjective: previousProposal?.campaignObjective || '', targetRegion: previousProposal?.targetRegion || '', targetLanguages: previousProposal?.targetLanguages || [], startDate: '', endDate: '', validUntil: '', internalSalesOwnerId: renewal.ownerId, internalSalesOwnerName: renewal.ownerName, items, taxRate: '0', approvalRequired: false }, rateCards, now); }
export function createPerformanceSnapshot(input: { recordType: MarketingPerformanceSnapshot['recordType']; recordId: string; metric: string; source: string; value: number }, actor: MarketingActor, now = new Date().toISOString()): { snapshot?: MarketingPerformanceSnapshot; error?: string } { if (!hasMarketingRight(actor, 'view_growth_performance')) return { error: 'Verified performance snapshots require view_growth_performance.' }; if (!Number.isFinite(Number(input.value))) return { error: 'Snapshot value must be verified numeric data.' }; return { snapshot: { id: createId('snap', now), recordType: input.recordType, recordId: clean(input.recordId), metric: clean(input.metric), source: clean(input.source), value: Number(input.value), capturedAt: now, capturedBy: actor.name, staffId: actor.staffId } }; }

export function filterAdvertisers(advertisers: MarketingAdvertiser[], filtersOrSearch: AdvertiserFilters | string, legacyStage: AdvertiserStage | 'all' = 'all', followUps: MarketingFollowUp[] = [], now = new Date()): MarketingAdvertiser[] { const filters: AdvertiserFilters = typeof filtersOrSearch === 'string' ? { search: filtersOrSearch, stage: legacyStage, industry: '', salesOwnerId: '', leadSource: '', followUpStatus: 'all', dateFilter: 'all', sort: 'newest' } : filtersOrSearch; const query = filters.search.trim().toLowerCase(); const today = now.toDateString(); const since = filters.dateFilter === 'last_7_days' ? Date.now() - 7 * 86400000 : filters.dateFilter === 'last_30_days' ? Date.now() - 30 * 86400000 : 0; return advertisers.filter((advertiser) => { if (advertiser.archivedAt) return false; if (filters.stage !== 'all' && advertiser.stage !== filters.stage) return false; if (filters.industry && advertiser.industry !== filters.industry) return false; if (filters.salesOwnerId && advertiser.salesOwnerId !== filters.salesOwnerId) return false; if (filters.leadSource && advertiser.leadSource !== filters.leadSource) return false; if (filters.dateFilter === 'today' && new Date(advertiser.createdAt).toDateString() !== today) return false; if (since && Date.parse(advertiser.createdAt) < since) return false; if (filters.followUpStatus !== 'all') { const statuses = followUps.filter((followUp) => followUp.advertiserId === advertiser.id).map((followUp) => followUpComputedStatus(followUp, now)); if (filters.followUpStatus === 'none' && statuses.length > 0) return false; if (filters.followUpStatus !== 'none' && !statuses.includes(filters.followUpStatus === 'due_today' ? 'due' : filters.followUpStatus)) return false; } if (!query) return true; return [advertiser.companyName, advertiser.industry, advertiser.contactPerson, advertiser.email, advertiser.city, advertiser.state, advertiser.salesOwnerName || '', advertiser.leadSource].some((value) => value.toLowerCase().includes(query)); }).sort((a, b) => { if (filters.sort === 'oldest') return Date.parse(a.createdAt) - Date.parse(b.createdAt); if (filters.sort === 'next_follow_up') return Date.parse(a.nextFollowUpAt || '9999-12-31') - Date.parse(b.nextFollowUpAt || '9999-12-31'); if (filters.sort === 'estimated_budget') return parseCurrencyToCents(b.estimatedBudget) - parseCurrencyToCents(a.estimatedBudget); if (filters.sort === 'last_contact') return Date.parse(b.lastContactAt || '1970-01-01') - Date.parse(a.lastContactAt || '1970-01-01'); return Date.parse(b.createdAt) - Date.parse(a.createdAt); }); }

function normalizeAdvertiser(raw: any): MarketingAdvertiser { const now = clean(raw?.createdAt) || new Date().toISOString(); const form = { ...createEmptyAdvertiserForm(), ...raw, contactPerson: clean(raw?.contactPerson || raw?.contacts?.[0]?.name), email: clean(raw?.email || raw?.contacts?.[0]?.email), phone: clean(raw?.phone || raw?.contacts?.[0]?.phone), designation: clean(raw?.designation || raw?.contacts?.[0]?.designation) }; const created = createAdvertiserFromForm(form, now); return { ...created, ...raw, contacts: Array.isArray(raw?.contacts) && raw.contacts.length ? raw.contacts : created.contacts, notesHistory: Array.isArray(raw?.notesHistory) ? raw.notesHistory : [], interactions: Array.isArray(raw?.interactions) ? raw.interactions : [], activity: Array.isArray(raw?.activity) ? raw.activity : created.activity, handoffStatus: raw?.handoffStatus || 'not_sent', updatedAt: clean(raw?.updatedAt) || now }; }
function normalizePromotion(raw: any): MarketingPromotion { const now = clean(raw?.createdAt) || new Date().toISOString(); return { id: clean(raw?.id) || createId('promo', now), campaignName: clean(raw?.campaignName), objective: PROMOTION_OBJECTIVES.includes(raw?.objective) ? raw.objective : 'Website Traffic', description: clean(raw?.description), destinationType: PROMOTION_DESTINATION_TYPES.includes(raw?.destinationType) ? raw.destinationType : 'Homepage', destinationUrl: clean(raw?.destinationUrl), primaryLanguage: PROMOTION_LANGUAGES.includes(raw?.primaryLanguage) ? raw.primaryLanguage : 'All', targetRegion: PROMOTION_REGIONS.includes(raw?.targetRegion) ? raw.targetRegion : 'India', customRegion: clean(raw?.customRegion), channels: Array.isArray(raw?.channels) ? raw.channels.filter((item: any) => PROMOTION_CHANNELS.includes(item)) : [], startDate: clean(raw?.startDate), endDate: clean(raw?.endDate), ownerId: clean(raw?.ownerId), ownerName: clean(raw?.ownerName), priority: PROMOTION_PRIORITIES.includes(raw?.priority) ? raw.priority : 'Normal', status: PROMOTION_STATUSES.includes(raw?.status) ? raw.status : 'Draft', notes: clean(raw?.notes), partnerId: clean(raw?.partnerId), archivedAt: clean(raw?.archivedAt), archivedBy: clean(raw?.archivedBy), learnings: raw?.learnings && typeof raw.learnings === 'object' ? raw.learnings : undefined, links: Array.isArray(raw?.links) ? raw.links : [], calendarItems: Array.isArray(raw?.calendarItems) ? raw.calendarItems : [], channelActivities: Array.isArray(raw?.channelActivities) ? raw.channelActivities : [], activity: Array.isArray(raw?.activity) ? raw.activity : [], createdAt: now, updatedAt: clean(raw?.updatedAt) || now }; }
function normalizeCampaignReport(raw: any): MarketingCampaignReport { const now = clean(raw?.createdAt) || new Date().toISOString(); return { id: clean(raw?.id) || createId('report', now), reportType: raw?.reportType === 'Promotion Campaign' ? 'Promotion Campaign' : 'Advertiser Campaign', advertiserId: clean(raw?.advertiserId), dealId: clean(raw?.dealId), proposalId: clean(raw?.proposalId), handoffId: clean(raw?.handoffId), promotionId: clean(raw?.promotionId), adsManagerCampaignId: clean(raw?.adsManagerCampaignId), analyticsCampaignKey: clean(raw?.analyticsCampaignKey), campaignName: clean(raw?.campaignName), campaignObjective: clean(raw?.campaignObjective), campaignStart: clean(raw?.campaignStart), campaignEnd: clean(raw?.campaignEnd), placements: Array.isArray(raw?.placements) ? raw.placements.map((item: any) => clean(item)).filter(Boolean) : [], status: CAMPAIGN_REPORT_STATUSES.includes(raw?.status) ? raw.status : 'Draft', metrics: normalizePerformanceMetrics(raw?.metrics), summary: clean(raw?.summary), campaignNotes: clean(raw?.campaignNotes), observations: clean(raw?.observations), recommendations: clean(raw?.recommendations), preparedBy: clean(raw?.preparedBy), preparedByStaffId: clean(raw?.preparedByStaffId), preparedAt: clean(raw?.preparedAt), createdBy: clean(raw?.createdBy), createdByStaffId: clean(raw?.createdByStaffId), createdAt: now, sharedBy: clean(raw?.sharedBy), sharedByStaffId: clean(raw?.sharedByStaffId), sharedAt: clean(raw?.sharedAt), archivedAt: clean(raw?.archivedAt), activity: Array.isArray(raw?.activity) ? raw.activity : [] }; }
function normalizeRenewal(raw: any): MarketingRenewal { const now = clean(raw?.createdAt) || new Date().toISOString(); return { id: clean(raw?.id) || createId('renewal', now), advertiserId: clean(raw?.advertiserId), previousDealId: clean(raw?.previousDealId), previousCampaignId: clean(raw?.previousCampaignId), previousProposalId: clean(raw?.previousProposalId), previousCampaignValue: clean(raw?.previousCampaignValue), campaignEndDate: clean(raw?.campaignEndDate), suggestedFollowUpDate: clean(raw?.suggestedFollowUpDate), ownerId: clean(raw?.ownerId), ownerName: clean(raw?.ownerName), status: RENEWAL_STATUSES.includes(raw?.status) ? raw.status : 'Upcoming', notes: clean(raw?.notes), archivedAt: clean(raw?.archivedAt), activity: Array.isArray(raw?.activity) ? raw.activity : [], createdAt: now, updatedAt: clean(raw?.updatedAt) || now }; }
export function normalizeMarketingData(input: unknown): MarketingData { const empty = createEmptyMarketingData(); if (Array.isArray(input)) return { ...empty, advertisers: input.map((item) => normalizeAdvertiser(item)) }; if (!input || typeof input !== 'object') return empty; const raw = input as Partial<MarketingData>; return { advertisers: Array.isArray(raw.advertisers) ? raw.advertisers.map((item) => normalizeAdvertiser(item)) : [], followUps: Array.isArray(raw.followUps) ? raw.followUps : [], proposals: Array.isArray(raw.proposals) ? raw.proposals : [], deals: Array.isArray(raw.deals) ? raw.deals : [], partnerships: Array.isArray(raw.partnerships) ? raw.partnerships : [], rateCards: Array.isArray(raw.rateCards) ? raw.rateCards : [], handoffs: Array.isArray(raw.handoffs) ? raw.handoffs : [], promotions: Array.isArray(raw.promotions) ? raw.promotions.map((item) => normalizePromotion(item)) : [], growthGoals: Array.isArray(raw.growthGoals) ? raw.growthGoals : [], campaignReports: Array.isArray(raw.campaignReports) ? raw.campaignReports.map((item) => normalizeCampaignReport(item)) : [], renewals: Array.isArray(raw.renewals) ? raw.renewals.map((item) => normalizeRenewal(item)) : [], performanceSnapshots: Array.isArray(raw.performanceSnapshots) ? raw.performanceSnapshots : [], utmPresets: Array.isArray(raw.utmPresets) && raw.utmPresets.length ? raw.utmPresets : DEFAULT_UTM_PRESETS, contentQueue: Array.isArray(raw.contentQueue) ? raw.contentQueue : [], settings: { ...empty.settings, ...(raw.settings || {}) } }; }
